/* Architecture and request-specific output audits. No model inference. */
(function(root){
 'use strict';
 const esc=value=>String(value??'Not supplied').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=(value,d=2)=>Number(value).toLocaleString('en-IN',{maximumFractionDigits:d});
 const table=(headers,rows)=>`<div class="audit-table"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 const lane=(title,items)=>`<article class="architecture-lane"><h2>${title}</h2><ol>${items.map(([name,note])=>`<li><b>${name}</b><span>${note}</span></li>`).join('')}</ol></article>`;
 function architectureMarkup(){return `<section id="architecture" class="page" hidden>${root.PaddyArchitecture.markup(false)}</section>`;}
 function yieldPanel(request,reference,summary){
  const model=request.proposedModel==='mlp'?'MLP regressor':'HistGradientBoostingRegressor';
  const rows=[['District',request.district,'User selection'],['State',request.state,'Selected district'],['Season',request.season,'User selection'],['Year',request.year,'User input'],['Cultivation area',`${num(request.areaHa)} ha`,'User input / what-if control'],['Demo yield',`${num(request.illustrativeYieldTPerHa)} t/ha`,'Manual assumption — not a model result']];
  const weather=reference?table(['Retrieved historical field','Value','Use in this output'],[['Average temperature',`${num(reference.TAVG_MEAN)} °C`,'Reference only'],['Season precipitation',`${num(reference.PREC_TOTAL)} mm`,'Reference only'],['Growing degree days (base 10)',num(reference.GDD_BASE10),'Reference only'],['Historical crop area',`${num(reference.CROP_AREA)} ha`,'Reference only'],['Observed yield',`${num(reference.YIELD,3)} t/ha`,'Comparison label, not an input to the demo yield']]):'<p>No unique district/year/season row matched. No historical weather values were retrieved or invented.</p>';
  const price=summary?.priceINRPerKg;
  return `<details class="prediction-audit"><summary>Show prediction flow <span>Inputs · retrieved data · calculations</span></summary><div class="prediction-audit-body"><p class="audit-status">Executed now: browser-local preview and arithmetic. Trained-model inference: not executed.</p><ol class="request-flow"><li><b>1. Take the input</b>${table(['Input','Value','Origin'],rows)}</li><li><b>2. Match the historical reference</b><p>Match the bundled observations by selected district, year and season. No live weather API is called. These fields do not calculate the manual demo yield.</p>${weather}</li><li><b>3. Identify the selected model route</b><div class="flow"><span>21 numerical features + state / season</span><b>→</b><span>Saved imputer / scaler / encoder${request.representation==='autoencoder'?' + DAE':''}</span><b>→</b><span>${request.representation==='autoencoder'?'16':'28'} predictors</span><b>→</b><span>${model}</span></div><p>Proposed route only. The complete model features are not fetched or preprocessed in this browser preview; no predictor weights are loaded. After integration, this section must record the actual feature values, provenance and model version.</p></li><li><b>4. Calculate the displayed values</b><code>Production = ${num(request.illustrativeYieldTPerHa)} t/ha × ${num(request.areaHa)} ha = ${num(request.illustrativeYieldTPerHa*request.areaHa)} t<br>Mass = ${num(request.illustrativeYieldTPerHa*request.areaHa)} t × 1,000 = ${num(request.illustrativeYieldTPerHa*request.areaHa*1000)} kg</code>${summary?`<p>Area scenario: ${num(summary.yieldTPerHa)} t/ha × ${num(summary.scenario.areaHa)} ha = ${num(summary.scenario.productionTonnes)} t.</p>`:''}${price!==null&&price!==undefined?`<p>Gross value: ${num(summary.productionKg)} kg × ₹${num(price)}/kg = ₹${num(summary.grossValueINR)}. This is not profit.</p>`:'<p>Gross value is not calculated until a valid sale-price assumption is entered.</p>'}</li></ol>${root.DetectionFlow.influenceMarkup(request)}</div></details>`;
 }
 function imagePanel(request){
  const image=request.image;
  return `<details class="prediction-audit"><summary>Show prediction flow <span>Photo checks · image model · output</span></summary><div class="prediction-audit-body"><p class="audit-status">Executed now: file validation and local preview. Classification and softmax: not executed.</p><ol class="request-flow"><li><b>1. Take and validate the photo</b>${table(['Checked field','Actual value'],[['Format',image.mimeType],['Image size',`${num(image.width,0)} × ${num(image.height,0)} pixels`],['File size',`${num(image.bytes/1024)} KB`],['Validation','Supported signature, decoded dimensions and size limits passed']])}</li><li><b>2. Prepare the model input — pending integration</b><p>Correct orientation → RGB → resize shorter edge to 256 → centre-crop 224 × 224 → tensor.</p><code>Normalized channel = (pixel / 255 − mean) / standard deviation<br>Mean: [0.485, 0.456, 0.406]<br>Standard deviation: [0.229, 0.224, 0.225]</code><p>These transforms are configured in the Python runner; they are not executed by this photo preview.</p></li><li><b>3. Classify with EfficientNet-B0 — pending training</b><div class="flow"><span>3 × 224 × 224 image tensor</span><b>→</b><span>EfficientNet-B0</span><b>→</b><span>4 output logits</span><b>→</b><span>Softmax</span><b>→</b><span>Candidate label</span></div><code>pᵢ = exp(zᵢ) / Σ exp(zⱼ)<br>Candidate = class with the highest pᵢ</code><p>No logits, scores or label exist for this photo yet. Supported classes: bacterial leaf blight, blast, brown spot and healthy. Softmax does not reliably reject unsupported crops or diseases.</p></li><li><b>4. Keep context separate</b>${table(['Context','Selected value','Use'],[['District',request.context.district,'Reference guidance only'],['State',request.context.state,'Reference guidance only'],['Season',request.context.season,'Reference guidance only'],['Crop year',request.context.year,'Reference guidance only']])}<p>The model receives pixels, not weather measurements. Image-region importance is not computed. No confidence percentages, weather-feature rankings or disease-related yield losses are fabricated.</p></li></ol></div></details>`;
 }
 root.PredictionFlow={architectureMarkup,yieldPanel,imagePanel,mode:'yield'};
 if(typeof module!=='undefined'&&module.exports)module.exports=root.PredictionFlow;
 if(typeof document==='undefined')return;
 const main=document.getElementById('main');
 main.insertAdjacentHTML('beforeend',architectureMarkup());
 root.PaddyArchitecture.mount(document.getElementById('architecture'),false);
 const outputs=document.createElement('section');outputs.id='results';outputs.className='page';outputs.hidden=true;outputs.innerHTML='<div class="page-intro"><div><p class="eyebrow">RESULTS</p><h1>Output</h1><p class="intro-copy">Results and request-specific computation details.</p></div><a class="inline-link" href="#studio">Change yield inputs →</a></div><nav class="output-tabs" aria-label="Output type"><a href="#results">Yield result</a><a href="#image-results">Photo result</a></nav><div id="image-result" hidden><div class="empty-result"><div><h3>No photo output yet</h3><p>Choose a rice photo, then select View photo output.</p><a class="inline-link" href="#health">Go to crop health →</a></div></div></div>';
 outputs.append(document.querySelector('.result-section'));main.append(outputs);
 const nav=document.querySelector('nav[aria-label="Main"]');nav.innerHTML='<a href="#studio" class="nav-link">Yield studio</a><a href="#health" class="nav-link">Crop health</a><a href="#results" class="nav-link">Output</a><a href="#architecture" class="nav-link">Architecture</a>';
 document.querySelector('.photo-method')?.remove();
 document.querySelector('#health .intro-note')?.remove();
 document.querySelector('.photo-section').classList.add('photo-section-simple');
 document.getElementById('prepare-screening').textContent='View photo output →';
 const infoModelNote=document.querySelector('#models-section > p:last-child');if(infoModelNote?.textContent.startsWith('LSTM'))infoModelNote.remove();
 root.PredictionFlow.showImage=function(request){
  root.PredictionFlow.mode='image';
  document.getElementById('image-result').innerHTML=`<article class="image-output-card"><p class="eyebrow">RICE PHOTO</p><h2>Photo validated</h2><p>Classification unavailable. The rice-image classifier is not trained or connected.</p><div class="image-output-meta"><span>${esc(request.image.mimeType)}</span><span>${num(request.image.width,0)} × ${num(request.image.height,0)} pixels</span><span>${num(request.image.bytes/1024)} KB</span></div><a class="inline-link" href="#health">Choose another photo →</a></article>${imagePanel(request)}`;
  location.hash='image-results';
 };
})(typeof window!=='undefined'?window:globalThis);
